//! Vectors from `testdata/proto/vectors.toml` (generated by `gen.mjs`, cross-checked with
//! meshcore.js; taken from loranet) and properties of the codec and the USB framing.

use mc_proto::{
    Command, DecodeError, DeviceReject, FROM_DEVICE, Response, TO_DEVICE, UsbDeframer, usb_frame,
};
use proptest::prelude::*;
use serde::Deserialize;

#[derive(Deserialize)]
struct File {
    command: Vec<Frame>,
    response: Vec<Frame>,
    device: Vec<Device>,
}

#[derive(Deserialize)]
struct Frame {
    name: String,
    hex: String,
    expect: String,
    dump: Option<String>,
}

#[derive(Deserialize)]
struct Device {
    name: String,
    hex: String,
    expect: String,
    canonical: Option<String>,
}

fn load() -> File {
    toml::from_str(include_str!("../../../testdata/proto/vectors.toml")).unwrap()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn kind(e: DecodeError) -> String {
    format!("err:{e:?}")
}

fn reject(e: DeviceReject) -> String {
    match e {
        DeviceReject::Ignored => "ignored".into(),
        DeviceReject::Err(c) => format!("err:{c}"),
    }
}

#[test]
fn command_vectors() {
    for v in load().command {
        let bytes = unhex(&v.hex);
        match Command::decode(&bytes) {
            Ok(c) => {
                assert_eq!(v.expect, "ok", "{} accepted", v.name);
                assert_eq!(Some(c.to_string()), v.dump, "{}", v.name);
                let mut out = [0u8; 256];
                let n = c.encode(&mut out).unwrap();
                assert_eq!(hex(&out[..n]), v.hex, "{} re-encoded", v.name);
                // Every canonical frame also passes on the device side, with the same meaning.
                assert_eq!(
                    Command::decode_device(&bytes),
                    Ok(c),
                    "{} on the device side",
                    v.name
                );
            }
            Err(e) => assert_eq!(kind(e), v.expect, "{}", v.name),
        }
    }
}

#[test]
fn response_vectors() {
    for v in load().response {
        let bytes = unhex(&v.hex);
        match Response::decode(&bytes) {
            Ok(r) => {
                assert_eq!(v.expect, "ok", "{} accepted", v.name);
                assert_eq!(Some(r.to_string()), v.dump, "{}", v.name);
                let mut out = [0u8; 256];
                let n = r.encode(&mut out).unwrap();
                assert_eq!(hex(&out[..n]), v.hex, "{} re-encoded", v.name);
            }
            Err(e) => assert_eq!(kind(e), v.expect, "{}", v.name),
        }
    }
}

/// `[[device]]` section: decoding like `MyMesh::handleCmdFrame`, then canonical form.
#[test]
fn device_vectors() {
    let file = load();
    assert!(file.device.len() > 100);
    for v in file.device {
        let bytes = unhex(&v.hex);
        match Command::decode_device(&bytes) {
            Ok(c) => {
                assert_eq!(v.expect, "ok", "{} accepted ({c})", v.name);
                let canonical = v.canonical.as_deref().expect("canonical form");
                let mut out = [0u8; 256];
                let n = c.encode(&mut out).unwrap();
                assert_eq!(hex(&out[..n]), canonical, "{} canonical form", v.name);
                assert_eq!(
                    Command::decode(&unhex(canonical)),
                    Ok(c),
                    "{} read back strictly",
                    v.name
                );
            }
            Err(e) => {
                assert_eq!(reject(e), v.expect, "{}", v.name);
                assert!(v.canonical.is_none(), "{}", v.name);
            }
        }
    }
}

#[test]
fn private_keys_are_never_displayed() {
    let key = [0xabu8; 64];
    let shown = [
        Command::ImportPrivateKey { key }.to_string(),
        Response::PrivateKey { key }.to_string(),
    ];
    for s in shown {
        assert!(!s.contains("abab"), "{s}");
    }
}

#[test]
fn encode_refuses_values_without_canonical_form() {
    let mut out = [0u8; 256];
    let bad = [
        Command::AddUpdateContact {
            key: [1; 32],
            kind: 1,
            flags: 0,
            path_len: 0,
            path: [0; 64],
            name: [0; 32],
            last_advert: 0,
            lat_lon: None,
            lastmod: Some(5),
        },
        Command::SetOtherParams {
            manual_add: 0,
            telemetry: None,
            advert_loc_policy: Some(1),
            multi_acks: None,
        },
        Command::SendRawData {
            path_len: 2,
            path: &[1],
            payload: &[1, 2, 3, 4],
        },
        Command::SendTracePath {
            tag: 0,
            auth: 0,
            flags: 1,
            path: &[1, 2, 3],
        },
        Command::SendTxtMsg {
            txt_type: 0,
            attempt: 0,
            timestamp: 0,
            prefix: [0; 6],
            text: &[0x41; 170],
        },
    ];
    for c in bad {
        assert!(c.encode(&mut out).is_err(), "{c:?}");
    }
    let bad = [
        Response::Other {
            code: 0x05,
            body: &[],
        },
        Response::TraceData {
            reserved: 0,
            flags: 0,
            tag: 0,
            auth: 0,
            hashes: &[1, 2],
            snrs: &[1],
            final_snr4: 0,
        },
        Response::AllowedRepeatFreq { ranges: &[0; 7] },
    ];
    for r in bad {
        assert!(r.encode(&mut out).is_err(), "{r:?}");
    }
}

/// Test frames: arbitrary bytes, or a known command or response code followed by a tail of
/// arbitrary length (known codes are rare among 256).
fn frames() -> impl Strategy<Value = Vec<u8>> {
    prop_oneof![
        prop::collection::vec(any::<u8>(), 0..200),
        (0u8..=70, prop::collection::vec(any::<u8>(), 0..180)).prop_map(|(c, mut t)| {
            t.insert(0, c);
            t
        }),
        (0x80u8..=0x92, prop::collection::vec(any::<u8>(), 0..180)).prop_map(|(c, mut t)| {
            t.insert(0, c);
            t
        }),
        // Short tails: length preconditions and fields read outside the frame.
        (0u8..=70, prop::collection::vec(any::<u8>(), 0..40)).prop_map(|(c, mut t)| {
            t.insert(0, c);
            t
        }),
    ]
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(4096))]

    #[test]
    fn any_accepted_frame_is_canonical(bytes in frames()) {
        let mut out = [0u8; 256];
        if let Ok(r) = Response::decode(&bytes) {
            let n = r.encode(&mut out).unwrap();
            prop_assert_eq!(&out[..n], &bytes[..]);
        }
        if let Ok(c) = Command::decode(&bytes) {
            let n = c.encode(&mut out).unwrap();
            prop_assert_eq!(&out[..n], &bytes[..]);
            // Device mode accepts every canonical frame, with the same meaning.
            prop_assert_eq!(Command::decode_device(&bytes), Ok(c));
        }
    }

    /// ADR-0002: every command accepted on the device side is written as a canonical frame that
    /// strict decoding reads back identically.
    #[test]
    fn device_accepted_reencodes_canonically(bytes in frames()) {
        match Command::decode_device(&bytes) {
            Ok(c) => {
                let mut out = [0u8; 256];
                let n = c.encode(&mut out).unwrap();
                prop_assert_eq!(Command::decode(&out[..n]), Ok(c));
            }
            Err(DeviceReject::Ignored) => {
                prop_assert!(bytes.is_empty() || bytes.len() > mc_proto::FRAME_MAX);
            }
            Err(DeviceReject::Err(code)) => prop_assert!(code == 1 || code == 6),
        }
    }

    #[test]
    fn usb_frames_survive_noise(
        noise in prop::collection::vec(any::<u8>().prop_filter("no start byte", |b| *b != FROM_DEVICE), 0..20),
        frames in prop::collection::vec(prop::collection::vec(any::<u8>(), 1..=176), 1..5),
    ) {
        let mut stream = noise.clone();
        for f in &frames {
            let mut buf = [0u8; 180];
            let n = usb_frame(FROM_DEVICE, f, &mut buf).unwrap();
            stream.extend_from_slice(&buf[..n]);
        }
        let mut d = UsbDeframer::new(FROM_DEVICE);
        let mut got = Vec::new();
        for b in stream {
            if let Some(f) = d.push(b) {
                got.push(f.to_vec());
            }
        }
        prop_assert_eq!(got, frames);
    }
}

#[test]
fn usb_frame_refuses_bad_sizes() {
    let mut buf = [0u8; 200];
    assert!(usb_frame(TO_DEVICE, &[], &mut buf).is_err());
    assert!(usb_frame(TO_DEVICE, &[0; 177], &mut buf).is_err());
    assert_eq!(usb_frame(TO_DEVICE, &[0x0a], &mut buf), Ok(4));
    assert_eq!(&buf[..4], &[b'<', 1, 0, 0x0a]);
}

/// ASI:58-66: a frame announced as longer than 176 bytes is read in full, truncated to 176, and
/// the rest of the stream is not mistaken for noise.
#[test]
fn usb_long_frame_is_truncated_like_the_cpp() {
    let mut stream = vec![b'<', 200, 0];
    stream.extend((0..200u8).map(|i| i ^ 0x5a));
    stream.extend([b'<', 1, 0, 0x0a]);
    let mut d = UsbDeframer::new(TO_DEVICE);
    let mut got = Vec::new();
    for b in stream {
        if let Some(f) = d.push(b) {
            got.push(f.to_vec());
        }
    }
    let first: Vec<u8> = (0..176u8).map(|i| i ^ 0x5a).collect();
    assert_eq!(got, vec![first, vec![0x0a]]);
}
